class CrossItemPeriodSwapNeighborhood:
    """Intercambia el estado de setup entre dos ítems en un período dado: (i1, i2, t)."""

    def __init__(self, problem):
        self.problem = problem

        # Cache acotada para reutilizar objetivos exactos de soluciones ya evaluadas.
        # Captura `problem` por cierre y evita recomputar el coste completo cuando
        # el mismo estado aparece repetidamente.
        @lru_cache(maxsize=8192)
        def _objective_cached(sol):
            return self.problem.objective(sol)

        self._objective_cached = _objective_cached

    def moves(self, sol):
        n_items = len(sol)
        n_periods = len(sol[0]) if n_items else 0
        for i1 in range(n_items):
            row1 = sol[i1]
            for t1 in range(n_periods):
                if not row1[t1]:
                    continue
                for i2 in range(n_items):
                    row2 = sol[i2]
                    for t2 in range(n_periods):
                        if row2[t2]:
                            continue
                        if i1 != i2 or t1 != t2:
                            yield (i1, t1, i2, t2)

    def apply(self, sol, m):
        i1, t1, i2, t2 = m
        s = [list(row) for row in sol]
        s[i1][t1] = False
        s[i2][t2] = True
        return self.problem.parts.canonical(tuple(tuple(row) for row in s))

    def delta(self, sol, m):
        # Exacto y más rápido cuando hay repetición de estados: la solución original
        # y/o la resultante suelen volver a consultarse muchas veces.
        obj_sol = self._objective_cached(sol)
        new_sol = self.apply(sol, m)
        return self._objective_cached(new_sol) - obj_sol


def build_component(problem, **params):
    return CrossItemPeriodSwapNeighborhood(problem)
